Item.method_code:
const itemType = options.itemType;
const isPolymorphic = ArasModules.metadata.itemType.isPolymorphic(itemType.id);
if (isPolymorphic) {
	return {
		hidden: true
	};
}
const state = options.getState();
const selectedRows = state.grid.selectedRows;
const selectedConfigIds = selectedRows.map(id =>
	options.rows.get(id, 'config_id')
);
const props = options.getProps();
const selectedFavorites = options.favorites.filterFavorites(props.favorites, 'Item', favorite =>
	selectedConfigIds.includes(favorite.additional_data.id));
const hidden = selectedFavorites.length === 0;
const disabled = selectedRows.length > 1;

return { hidden, disabled };
